export interface UseOverlayStateProps {
    /**
     * Whether the overlay is currently open (controlled)
     */
    isOpen?: boolean;
    /**
     * Whether the overlay is open by default (uncontrolled)
     * @default false
     */
    defaultOpen?: boolean;
